// The Action-side GitHub reader for the scheduler (per-project-scheduling
// DESIGN §10: packs/claudinite-tasks/ is the one place that legitimately uses the
// Action's GITHUB_TOKEN — everything session-side stays MCP-only). A minimal
// REST client over global fetch: `gh(path) -> { status, json }`, the same shape
// the fleet planner's injected reader uses, so the collectors read uniformly and
// test against a fake `gh`.
//
// `path` is an API path beginning with `/` (e.g. `/repos/owner/name/commits`);
// the base URL and auth are applied here. A non-2xx returns `{ status, json:
// null }` rather than throwing, so a 404 (no release yet, missing file) is data,
// not an error.

const API = process.env.GITHUB_API_URL || 'https://api.github.com';

export function makeGh({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
  // `gh(path)` reads; `gh(path, { method, body })` writes (body JSON-encoded).
  return async function gh(path, { method = 'GET', body } = {}) {
    const res = await fetchImpl(`${api}${path}`, {
      method,
      headers: {
        accept: 'application/vnd.github+json',
        'x-github-api-version': '2022-11-28',
        ...(token ? { authorization: `Bearer ${token}` } : {}),
        'user-agent': 'claudinite-scheduler',
        ...(body ? { 'content-type': 'application/json' } : {}),
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    });
    let json = null;
    try { json = await res.json(); } catch { json = null; }
    return { status: res.status, json };
  };
}

// The scheduler workflow's file name — the vendored shim's, identical in every
// member (the workflow is core, not pack content) and unchanged by the move to the
// work-item queue, which put the scheduler run at this same path. Named here rather than
// restated: the usage fold finds a repo's scheduler runs by it, to read their logs
// for the task-invocation records.
export const SCHEDULER_WORKFLOW_FILE = 'claudinite-scheduler.yml';

// The executor workflow's file name, same contract: identical in every member,
// and the target of every `workflow_dispatch` in the queue's chain (DESIGN §10) —
// the close-time drain, a run's own re-dispatch, and the failure continuation.
export const EXECUTOR_WORKFLOW_FILE = 'claudinite-executor.yml';

// The repo slug (owner/name) and default branch the workflow runs against, from
// the Actions environment. `GITHUB_REPOSITORY` is always set in a workflow;
// `GITHUB_REF_NAME` is the branch for a scheduled/dispatch run on the default branch.
export function actionRepoContext(env = process.env) {
  return {
    repo: env.GITHUB_REPOSITORY || null,
    defaultBranch: env.GITHUB_REF_NAME || 'main',
  };
}

// APPLYING a status transition — the write half of the vocabulary whose read half
// is `work-item.mjs`'s decode (tasks-dispatch DESIGN §4, the migration of #1119).
//
// One rule, and it is why this is not a plain `swapLabel`: the item may wear ANY
// engine version's spelling of the status it is leaving. A member's items outlive
// its converges, so an item filed as `task:ready` is picked up by an engine that
// writes `task:status:waiting-for-executor`, and a swap that named one spelling
// would leave the other standing — an item wearing two live statuses, which is the
// torn state the janitor exists to repair.
//
// Writes stay granular (add and remove named labels, never a set-write): with
// several executors and a scheduler run moving labels at once, a set-write from a
// stale snapshot clobbers a concurrent transition (DESIGN §4).
// The removes are UNCONDITIONAL — every spelling of the status being left, not
// only the ones the caller's snapshot shows. A caller holds the labels it read
// before its own earlier transitions, so filtering on that snapshot would skip
// exactly the label this engine just wrote; removing a label an issue does not
// carry 404s, which is the end state asked for and therefore success.
import { spellingsOf } from './work-item.mjs';

// Move `item` out of `fromStatus` (canonical — every spelling of it goes) and into
// the label `to`, which is whatever spelling this engine writes.
export async function swapStatus(api, gh, repo, item, fromStatus, to) {
  await clearStatus(api, gh, repo, item, fromStatus);
  return api.addLabel(gh, repo, item.number, to);
}

// Leave a status without entering another — the close path, where the terminal
// label is applied separately.
export async function clearStatus(api, gh, repo, item, status) {
  for (const label of spellingsOf(status)) {
    await api.removeLabel(gh, repo, item.number, label);
  }
}

