197	// THE status an issue wears, canonical, or null for one wearing none. A park wins
198	// over anything else present: a torn transition that left a state label beside a
199	// park must read as parked, or the queue would pick up an item a human owns.
200	export function statusOf(issue) {
201	  const worn = statusesOn(issue);
202	  return worn.find((s) => s.startsWith(PARK_PREFIX))
203	    ?? STATUS_LABELS.find((s) => worn.includes(s))
204	    ?? null;
205	}
